package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeColumn_TriageGen2Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveColumn_Success() {
        // Arrange
        Comparable rowKey1 = "Row1";
        Comparable rowKey2 = "Row2";
        Comparable colKey1 = "Col1";
        Comparable colKey2 = "Col2";
        Comparable colKey3 = "Col3";

        dataset.addObject("Val11", rowKey1, colKey1);
        dataset.addObject("Val12", rowKey1, colKey2);
        dataset.addObject("Val21", rowKey2, colKey1);
        dataset.addObject("Val23", rowKey2, colKey3);

        // Verify initial state
        assertEquals(3, dataset.getColumnCount());
        assertEquals("Val11", dataset.getObject(rowKey1, colKey1));

        // Act
        dataset.removeColumn(colKey1);

        // Assert
        // 1. Column key should be removed from columnKeys list
        List<Comparable> columnKeys = dataset.getColumnKeys();
        assertFalse("Column key should be removed from keys list", columnKeys.contains(colKey1));
        assertTrue(columnKeys.contains(colKey2));
        assertTrue(columnKeys.contains(colKey3));
        assertEquals(2, dataset.getColumnCount());

        // 2. Data should be removed from all rows
        assertNull("Value at colKey1 should be null/removed", dataset.getObject(rowKey1, colKey1));
        assertNull("Value at colKey1 should be null/removed", dataset.getObject(rowKey2, colKey1));

        // 3. Other data should remain intact
        assertEquals("Val12", dataset.getObject(rowKey1, colKey2));
        assertEquals("Val23", dataset.getObject(rowKey2, colKey3));
    }






}

