import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeColumn_TriageGen2Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }





    @Test
    public void testRemoveColumn_EmptyDataset() {
        // Arrange
        Comparable colKey = "Col1";

        // Act & Assert
        // Since getColumnIndex will return -1 if empty, this will throw exception
        try {
            dataset.removeColumn(colKey);
        } catch (UnknownKeyException e) {
            assertTrue(e.getMessage().contains("not recognised"));
        }
    }


}

package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeColumn_TriageGen2Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }







    @Test
    public void testRemoveColumn_WithNoRows() {
        // Arrange
        Comparable colKey = "Col1";
        // We need to add a column key without rows to test the iterator part 
        // However, in this implementation, columnKeys and rows are usually managed together.
        // If we can't add a column without a row via public API, we test the logic via existing paths.

        // To trigger the 'while(iterator.hasNext())' being false immediately:
        // We add a column key but ensure no rows have been added (this is hard with the provided API).
        // But if we add a row and then remove a column, the 'while' loop is covered.

        dataset.addObject("Val", "Row1", colKey);
        dataset.removeColumn(colKey);

        assertEquals(0, dataset.getColumnCount());
    }
}
